import { parentPort } from 'node:worker_threads';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { RaftNode, InMemoryStorage } from './index.mjs';

// Worker-side Raft runner. Hosts RaftNode + storage in the worker thread.
// - Transport in worker forwards outbound raft messages to main via postMessage
// - Apply runs in worker when configured, otherwise proxies committed entries to main and waits for ACK

let node = null;
let options = null;
let storage = null;

// Correlate apply(entry) calls with main-thread ACKs
const applyWaiters = new Map(); // reqId -> { resolve, reject }
let nextReqId = 1;

function isPathLike(spec) {
  return typeof spec === 'string' && (spec.startsWith('.') || spec.startsWith('/') || /^[A-Za-z]:[\\/]/.test(spec));
}

function resolveModuleSpecifier(spec) {
  if (typeof spec !== 'string') {
    throw new Error('Module specifier must be a string');
  }
  if (spec.startsWith('file:') || spec.startsWith('data:') || spec.startsWith('node:')) {
    return spec;
  }
  if (isPathLike(spec)) {
    return pathToFileURL(resolve(spec)).href;
  }
  return spec;
}

async function buildWorkerStorage(config) {
  if (!config || (!config.kind && !config.module)) {
    return new InMemoryStorage();
  }
  if (config.module) {
    const mod = await import(resolveModuleSpecifier(config.module));
    const exportName = config.export;
    const exported = exportName ? mod[exportName] : (mod.default ?? mod);
    if (!exported) {
      throw new Error('workerStorage export not found');
    }
    let instance = null;
    if (typeof exported === 'function') {
      try {
        instance = new exported(config.options || {});
      } catch (err) {
        const msg = String(err && (err.message || err));
        if (msg.includes('is not a constructor') || msg.includes('Class constructor')) {
          instance = exported(config.options || {});
        } else {
          throw err;
        }
      }
    } else {
      instance = exported;
    }
    if (!instance) {
      throw new Error('workerStorage export must be a constructor or object');
    }
    if (typeof instance.open === 'function') {
      instance.open();
    }
    return instance;
  }
  const kind = String(config.kind || '').toLowerCase();
  if (kind === 'inmemory' || kind === 'memory') {
    return new InMemoryStorage();
  }
  if (kind === 'sqlite') {
    const { SqliteStorage } = await import('./sqlite-storage.mjs');
    const instance = new SqliteStorage(config.options || {});
    if (typeof instance.open === 'function') {
      instance.open();
    }
    return instance;
  }
  throw new Error(`Unknown workerStorage kind: ${config.kind}`);
}

async function buildWorkerApply(config, context) {
  if (!config || !config.module) {
    throw new Error('workerApply.module is required');
  }
  const mod = await import(resolveModuleSpecifier(config.module));
  const exportName = config.export;
  const applyExport = exportName ? mod[exportName] : (mod.apply ?? mod.default);
  if (typeof applyExport !== 'function') {
    throw new Error('workerApply export must be a function');
  }
  const ctx = {
    id: context.id,
    storage: context.storage,
    options: config.options,
  };
  return async (entry) => {
    if (process?.env?.RAFT_DEBUG_WKR === '1') {
      try {
        const idx = Number(entry && (entry.index ?? entry.idx));
        console.log(`[wkr ${String(context.id)}] applyCommitted idx=${idx || 0}`);
      } catch {}
    }
    await applyExport(entry, ctx);
  };
}

function respond(reqId, result, error) {
  parentPort.postMessage({
    type: 'response',
    reqId,
    ...(error
      ? { error: String(error && error.message ? error.message : error), errorStack: error && error.stack }
      : { result }),
  });
}

function post(type, payload = {}, transferList) {
  parentPort.postMessage({ type, ...payload }, transferList);
}

parentPort.on('message', async (msg) => {
  const { type, reqId } = msg || {};
  try {
    switch (type) {
      case 'init': {
        // Store options used to construct the node
        const {
          id,
          peers,
          electionTick,
          heartbeatTick,
          tickIntervalMs,
          preVote,
          checkQuorum,
          debug,
          workerApply,
          workerStorage,
        } = msg;

        // Transport stub forwards outbound messages to main thread
        const transport = {
          async send(fromId, msgs) {
            // msgs is an array of JSON messages (WASM boundary schema)
            post('outbound', { fromId, msgs });
          },
        };

        storage = await buildWorkerStorage(workerStorage);

        let apply = null;
        if (workerApply) {
          apply = await buildWorkerApply(workerApply, { id: String(id), storage });
        } else {
          // Apply proxy: send to main, await ACK, then return.
          apply = async (entry) => {
            if (process?.env?.RAFT_DEBUG_WKR === '1') {
              try {
                const idx = Number(entry && (entry.index ?? entry.idx));
                console.log(`[wkr ${String(id)}] applyCommitted idx=${idx || 0}`);
              } catch {}
            }
            const applyReqId = nextReqId++;
            post('applyCommitted', { reqId: applyReqId, entries: [entry] });
            await new Promise((resolve, reject) => {
              applyWaiters.set(applyReqId, { resolve, reject });
            });
          };
        }

        options = {
          id: String(id),
          peers: Array.isArray(peers) ? peers.map(String) : [String(id)],
          electionTick: Number(electionTick),
          heartbeatTick: Number(heartbeatTick),
          preVote: !!preVote,
          checkQuorum: !!checkQuorum,
          tickIntervalMs: tickIntervalMs ?? 100,
          debug: !!debug,
        };

        node = new RaftNode({
          ...options,
          transport,
          storage,
          apply,
          onStateUpdate: (snapshot) => {
            try { post('stateUpdate', { snapshot }); } catch {}
          },
          onDrain: () => {
            try { post('drain', {}); } catch {}
          }
        });

        // Forward selected RaftNode events to the controller (main thread)
        try {
          if (typeof node.onCommitAdvanced === 'function') {
            node.onCommitAdvanced((evt) => {
              try { post('commitAdvanced', { commitIndex: Number(evt?.commitIndex) || 0, term: Number(evt?.term) || 0 }); } catch {}
            });
          }
          if (typeof node.onQuorumActive === 'function') {
            node.onQuorumActive((evt) => {
              try {
                post('quorumActive', {
                  term: Number(evt?.term) || 0,
                  majorityAcks: Number(evt?.majorityAcks) || 0,
                  quorumSize: Number(evt?.quorumSize) || 0,
                  leaderId: String(evt?.leaderId ?? options.id),
                });
              } catch {}
            });
          }
        } catch {}

        respond(reqId, { ok: true });
        break;
      }

      case 'start': {
        if (!node) throw new Error('Worker not initialized. Send init first.');
        await node.start();
        respond(reqId, { ok: true });
        break;
      }

      case 'stop': {
        if (node) {
          const { drainApply, drainTicks } = msg;
          await node.stop({ drainApply: !!drainApply, drainTicks: !!drainTicks });
          node = null;
        }
        if (storage && typeof storage.close === 'function') {
          try { storage.close(); } catch {}
        }
        storage = null;
        respond(reqId, { ok: true });
        break;
      }

      case 'status': {
        if (!node) throw new Error('Not running');
        const st = await node.status();
        respond(reqId, st);
        break;
      }

      case 'propose': {
        if (!node) throw new Error('Not running');
        let data = msg.data;
        if (data instanceof ArrayBuffer) {
          data = new Uint8Array(data);
        }
        // Uint8Array or string are accepted by RaftNode.propose
        await node.propose(data);
        respond(reqId, { ok: true });
        break;
      }

      case 'step': {
        if (!node) throw new Error('Not running');
        const { message } = msg;
        await node.step(message);
        respond(reqId, { ok: true });
        break;
      }

      case 'campaign': {
        if (!node) throw new Error('Not running');
        await node.campaign();
        respond(reqId, { ok: true });
        break;
      }

      case 'waitForCommit': {
        if (!node) throw new Error('Not running');
        const index = Number(msg.index);
        const localApply = !!msg.localApply;
        const timeout = Number(msg.timeout) || undefined;
        await node.waitForCommit(index, { localApply, timeout });
        respond(reqId, { ok: true });
        break;
      }

      case 'applyAck': {
        const waiter = applyWaiters.get(msg.reqId);
        if (waiter) {
          applyWaiters.delete(msg.reqId);
          if (msg.error) {
            waiter.reject(new Error(msg.error));
          } else {
            waiter.resolve();
          }
        }
        // no response frame for acks
        break;
      }

      case 'manualTick': {
        if (!node) throw new Error('Not running');
        await node._tick();
        respond(reqId, { ok: true });
        break;
      }

      case 'advanceTicks': {
        if (!node) throw new Error('Not running');
        const n = Number(msg.n) || 0;
        for (let i = 0; i < n; i++) {
          await node._tick();
        }
        respond(reqId, { ok: true });
        break;
      }

      default: {
        // Unknown message type
        if (reqId) {
          respond(reqId, null, new Error(`Unknown message type: ${type}`));
        } else {
          post('error', { message: `Unknown message type: ${type}` });
        }
      }
    }
  } catch (err) {
    if (reqId) {
      respond(reqId, null, err);
    } else {
      post('error', { message: String(err && err.message ? err.message : err), stack: err && err.stack });
    }
  }
});

// If the parent disconnects, attempt a clean stop
parentPort.on('close', async () => {
  try {
    if (node) await node.stop();
  } catch {}
  try {
    if (storage && typeof storage.close === 'function') {
      storage.close();
    }
  } catch {}
});
